pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool isOwner) public {
        address actor = isOwner ? c.Owner() : address(uint160(uint256(keccak256(abi.encodePacked(amount, isOwner)))));
        vm.assume(actor != address(0) && actor != c.Owner() && amount > 0 && amount < type(uint128).max);

        // Deploy an adversarial helper that reverts on value transfer
        Reverter reverter = new Reverter();

        // Fund the contract and actor
        vm.deal(address(c), amount);
        vm.deal(actor, amount);

        // Record initial Owner balance
        uint256 initialOwnerBalance = address(c.Owner()).balance;

        // Drive through Command targeting the reverter
        vm.prank(actor);
        try c.Command{value: amount}(address(reverter), abi.encodeWithSignature("revert()")) {} catch {}

        // In the reference contract, only the Owner can call Command.
        // If actor is not Owner, the Command call reverts, and no state changes.
        // Therefore, the Owner's balance should remain equal to initialOwnerBalance.
        // The buggy mutant replaces `require(msg.sender == Owner)` with `require(msg.sender != Owner)`,
        // allowing non-owners to call Command and potentially withdraw via multiplicate or reentrancy.
        // Here, the adversary (actor) is non-Owner in the buggy case and can trigger Command,
        // but the low-level call to Reverter fails, leaving funds in the contract.
        // A subsequent withdraw by the Owner should always succeed and return the same amount
        // in the correct contract. In the buggy contract, the non-owner could have called Command
        // and drained funds via multiplicate, causing a discrepancy.
        // The assertion checks that the Owner's balance hasn't mysteriously decreased,
        // which would indicate unauthorized fund movement.
        assertTrue(address(c.Owner()).balance == initialOwnerBalance);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

