pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool isOwner) public {
        // keep amount wide but cap to prevent overflow in helper
        amount = bound(amount, 0, type(uint256).max / 2);

        // actor is either the owner (msg.sender in setUp = this contract) or a non-owner
        address actor = isOwner ? address(this) : address(0xbeef);

        // deploy a helper that reverts on receiving ether
        Reverter reverter = new Reverter();

        // give the contract some ether
        vm.deal(address(c), amount);
        require(address(c).balance == amount, "setup funding failed");

        // The owner calls Command to transfer the entire balance to the reverting helper.
        // In the reference, this requires actor == owner -> isOwner must be true.
        // In the mutant, this requires actor != owner -> isOwner must be false.
        // Because the helper reverts, this transfer will always fail, and the balance should remain unchanged.
        vm.prank(actor);
        c.Command(address(reverter), hex"");

        // Try to withdraw.  This must succeed only for the owner.
        bool withdrawOk;
        try c.withdraw() { withdrawOk = true; } catch { withdrawOk = false; }

        // The property: after a failing Command, only the owner can withdraw.
        // The reference satisfies: withdrawOk == (actor == Owner).
        // The mutant violates: a non-owner (actor != Owner) can withdraw after the reverting Command.
        assertTrue(withdrawOk == isOwner);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

