contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. restrict domain: we need a non-zero initial balance so the Owner
        //    can withdraw something.
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint96).max); // keep reasonable
        // fund the Owner
