        vm.deal(owner, amount);

        // 2. give some Ether to the contract so withdraw has something to move.
        //    we use the Owner's own Ether to keep pranks simple.
        vm.prank(owner);
        (bool ok, ) = payable(address(c)).call{value: amount}("");
        require(ok, "funding failed");

        // record pre-state
        uint256 contractPre = address(c).balance;
        uint256 ownerPre = owner.balance;

        // 3. perform the withdraw as Owner (will always succeed because msg.sender == Owner)
        vm.prank(owner);
        c.withdraw();

        uint256 contractPost = address(c).balance;
        uint256 ownerPost = owner.balance;

        // 4. universal rule: after a successful withdraw, the contract's
        //    balance must be strictly less than the sum of the Owner's
        //    balance and the contract's pre-balance.  Intuitively the Owner
        //    received all the contract's previous Ether, so the sum "owner
        //    balance after + contract balance after" cannot be smaller than
        //    the pre-balance.  For a full withdraw the sum is exactly
        //    equal; the inequality `contractPost < ownerPost` catches the
        //    bug where only half is transferred.
        assertTrue(contractPost < ownerPost);
    }
}

